// Session usage is identical to regular HTTP session
@RestController
public class UserController {
    @PostMapping("/login")
    public ResponseEntity<Void> login(@RequestBody LoginRequest req, HttpSession session) {
        User user = authService.authenticate(req.getUsername(), req.getPassword());
        session.setAttribute("userId", user.getId());  // stored in Redis
        return ResponseEntity.ok().build();
    }

    @GetMapping("/profile")
    public UserDTO getProfile(HttpSession session) {
        Long userId = (Long) session.getAttribute("userId");  // fetched from Redis
        return userService.getUserById(userId);
    }
}
