## Sliding Window Rate Limiter

```java
@Component
public class RedisRateLimiter {

    private final StringRedisTemplate redis;
    private static final int MAX_REQUESTS = 100;
    private static final Duration WINDOW = Duration.ofMinutes(1);

    public boolean isAllowed(String identifier) {
        String key = "rate_limit:" + identifier;
        long now = System.currentTimeMillis();
        long windowStart = now - WINDOW.toMillis();

        // Atomic Lua script: remove old entries, add current, check count
        String luaScript = """
            local key = KEYS[1]
            local now = tonumber(ARGV[1])
            local windowStart = tonumber(ARGV[2])
            local maxRequests = tonumber(ARGV[3])
            local windowMs = tonumber(ARGV[4])

            -- Remove requests outside the sliding window
            redis.call('ZREMRANGEBYSCORE', key, 0, windowStart)

            -- Count current requests
            local count = redis.call('ZCARD', key)

            if count < maxRequests then
                -- Add this request
                redis.call('ZADD', key, now, now .. '-' .. math.random())
                redis.call('PEXPIRE', key, windowMs)
                return 1  -- allowed
            else
                return 0  -- rate limited
            end
            """;

        Long result = redis.execute(
            new DefaultRedisScript<>(luaScript, Long.class),
            List.of(key),
            String.valueOf(now),
            String.valueOf(windowStart),
            String.valueOf(MAX_REQUESTS),
            String.valueOf(WINDOW.toMillis())
        );

        return Long.valueOf(1L).equals(result);
    }
}

// Filter applying rate limiting
@Component
@Order(1)
public class RateLimitFilter extends OncePerRequestFilter {

    private final RedisRateLimiter rateLimiter;

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
            FilterChain chain) throws IOException, ServletException {
        String ip = req.getRemoteAddr();
        if (!rateLimiter.isAllowed(ip)) {
            res.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());
            res.setHeader("Retry-After", "60");
            res.getWriter().write("{\"error\": \"Rate limit exceeded\"}");
            return;
        }
        chain.doFilter(req, res);
    }
}
```

## Write-Through with @CachePut

```java
@Service
public class ProductService {

    // @Cacheable: check cache first
    @Cacheable(value = "products", key = "#id")
    public ProductDTO getProduct(Long id) {
        return productRepo.findById(id).map(ProductDTO::from).orElseThrow();
    }

    // @CachePut: ALWAYS write to cache with return value (write-through)
    @CachePut(value = "products", key = "#result.id")
    @Transactional
    public ProductDTO updateProduct(Long id, UpdateProductRequest req) {
        Product product = productRepo.findById(id).orElseThrow();
        product.update(req);
        Product saved = productRepo.save(product);  // write to DB
        return ProductDTO.from(saved);              // returned value goes to cache
        // Cache updated AFTER DB write — consistent
    }

    // @CacheEvict: remove from cache (for deletes)
    @CacheEvict(value = "products", key = "#id")
    @Transactional
    public void deleteProduct(Long id) {
        productRepo.deleteById(id);
    }
}
```

## Write-Behind Pattern (Custom Implementation)

```java
@Service
public class ViewCountService {

    private final StringRedisTemplate redis;
    private final ArticleRepository articleRepo;

    // Write to cache immediately — fast return to caller
    public long incrementViews(Long articleId) {
        String key = "article:views:" + articleId;
        return redis.opsForValue().increment(key);
    }

    // Background flush to DB — every 5 minutes
    @Scheduled(fixedDelay = 300_000)
    @Transactional
    public void flushViewCounts() {
        Set<String> keys = redis.keys("article:views:*");
        if (keys == null) return;

        for (String key : keys) {
            String articleIdStr = key.replace("article:views:", "");
            Long articleId = Long.parseLong(articleIdStr);
            String countStr = redis.opsForValue().getAndDelete(key);

            if (countStr != null && Long.parseLong(countStr) > 0) {
                // Flush accumulated views to DB
                articleRepo.incrementViewCount(articleId, Long.parseLong(countStr));
            }
        }
    }
}
// Risk: if Redis crashes before flush, view counts for that period are lost
// Acceptable for view counts; NOT acceptable for order data or financial transactions
