// Simple, purpose-built for distributed scheduled jobs
@Scheduled(fixedDelay = 60_000)
@SchedulerLock(name = "data-sync-job",
               lockAtLeastFor = "PT30S",  // hold at least 30s (prevent rapid re-run)
               lockAtMostFor = "PT5M")    // release after 5min even if not explicitly released
public void syncData() {
    // Only one instance runs this at a time
    performDataSync();
}
