## Cache Warming on Startup

```java
@Component
public class CacheWarmupService implements ApplicationListener<ApplicationReadyEvent> {

    private final CacheManager cacheManager;
    private final ProductRepository productRepo;
    private final CategoryRepository categoryRepo;
    private volatile boolean warmed = false;

    @Override
    public void onApplicationEvent(ApplicationReadyEvent event) {
        log.info("Starting cache warmup...");
        try {
            warmProductCache();
            warmCategoryCache();
            warmed = true;
            log.info("Cache warmup complete");
        } catch (Exception ex) {
            log.error("Cache warmup failed — proceeding without warm cache", ex);
            warmed = true;  // don't block startup on warmup failure
        }
    }

    private void warmProductCache() {
        // Load top 1000 most-viewed products
        List<Product> hotProducts = productRepo.findTop1000ByOrderByViewCountDesc();
        Cache cache = cacheManager.getCache("products");
        hotProducts.forEach(p -> cache.put(p.getId(), ProductDTO.from(p)));
        log.info("Warmed {} products into cache", hotProducts.size());
    }

    private void warmCategoryCache() {
        // Load all categories (small, changes rarely)
        List<Category> categories = categoryRepo.findAll();
        Cache cache = cacheManager.getCache("categories");
        categories.forEach(c -> cache.put(c.getSlug(), CategoryDTO.from(c)));
    }

    public boolean isWarmed() { return warmed; }
}

// Custom health indicator — reports down until cache is warm
@Component
public class CacheWarmupHealthIndicator implements HealthIndicator {
    private final CacheWarmupService warmupService;

    @Override
    public Health health() {
        if (warmupService.isWarmed()) {
            return Health.up().withDetail("cache", "warmed").build();
        }
        return Health.down().withDetail("cache", "warming in progress").build();
    }
}
